package com.hkdn.backend.service;

import com.hkdn.backend.dto.*;import com.hkdn.backend.entity.*;import com.hkdn.backend.exception.*;import com.hkdn.backend.repository.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.data.domain.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.util.StringUtils;import org.springframework.web.multipart.MultipartFile;import java.io.*;import java.nio.file.*;import java.util.*;

@Service public class MaterialService {
 private final MaterialRepository materials;private final MaterialVersionRepository versions;private final UserRepository users;private final HashService hashes;private final Path storageRoot;private final long maxBytes;
 public MaterialService(MaterialRepository materials,MaterialVersionRepository versions,UserRepository users,HashService hashes,@Value("${storage.root:./storage}") String root,@Value("${storage.max-file-size:10485760}") long maxBytes){this.materials=materials;this.versions=versions;this.users=users;this.hashes=hashes;this.storageRoot=Paths.get(root).toAbsolutePath().normalize();this.maxBytes=maxBytes;}
 @Transactional public Material create(MaterialCreateRequest r,UUID owner){Material m=new Material();m.setTitle(r.title().trim());m.setDescription(r.description());m.setSubject(r.subject());m.setOwner(users.findWithRolesById(owner).orElseThrow(()->new ResourceNotFoundException("Owner not found")));return materials.save(m);}
 @Transactional(readOnly=true) public Page<Material> list(String q,Pageable p){String query=q==null?"":q.trim();return materials.findByTitleContainingIgnoreCaseOrSubjectContainingIgnoreCase(query,query,p);}
 @Transactional(readOnly=true) public Material get(UUID id){return find(id);}
 @Transactional public Material update(UUID id,MaterialUpdateRequest r){Material m=find(id);m.setTitle(r.title().trim());m.setDescription(r.description());m.setSubject(r.subject());return m;}
 @Transactional public MaterialVersion upload(UUID id,MultipartFile file,UUID actor){if(file==null||file.isEmpty())throw new BusinessException("A PDF file is required");if(file.getSize()>maxBytes)throw new BusinessException("File exceeds configured size limit");String contentType=Optional.ofNullable(file.getContentType()).orElse("");String originalName=Optional.ofNullable(file.getOriginalFilename()).orElse("document.pdf");if(!"application/pdf".equalsIgnoreCase(contentType)&&!originalName.toLowerCase(Locale.ROOT).endsWith(".pdf"))throw new BusinessException("Only PDF files are accepted");Material m=find(id);int number=m.getCurrentVersion();String safeName=StringUtils.cleanPath(originalName);if(safeName.contains(".."))throw new BusinessException("Invalid file name");String key=id+"/v"+number+"-"+UUID.randomUUID()+".pdf";Path destination=storageRoot.resolve(key).normalize();if(!destination.startsWith(storageRoot))throw new BusinessException("Invalid storage path");try{Files.createDirectories(destination.getParent());byte[] bytes=file.getBytes();Files.write(destination,bytes,StandardOpenOption.CREATE_NEW);MaterialVersion v=new MaterialVersion();v.setMaterial(m);v.setVersionNumber(number);v.setOriginalFilename(safeName);v.setStorageKey(key);v.setContentType("application/pdf");v.setFileSize(bytes.length);v.setContentHash(hashes.sha256(bytes));v.setUploadedBy(users.findWithRolesById(actor).orElseThrow());MaterialVersion saved=versions.save(v);m.setCurrentVersion(number+1);materials.save(m);return saved;}catch(IOException e){throw new BusinessException("Unable to store uploaded file");}}
 @Transactional(readOnly=true) public List<MaterialVersion> versions(UUID id){find(id);return versions.findByMaterialIdOrderByVersionNumberDesc(id);}
 @Transactional(readOnly=true) public ResourceFile download(UUID versionId){MaterialVersion v=versions.findById(versionId).orElseThrow(()->new ResourceNotFoundException("Material version not found"));Path file=storageRoot.resolve(v.getStorageKey()).normalize();if(!file.startsWith(storageRoot)||!Files.exists(file))throw new ResourceNotFoundException("Stored file not found");try{return new ResourceFile(v,Files.readAllBytes(file));}catch(IOException e){throw new BusinessException("Unable to read stored file");}}
 @Transactional public void archive(UUID id){Material m=find(id);m.setStatus(MaterialStatus.ARCHIVED);m.setArchivedAt(java.time.Instant.now());}
 private Material find(UUID id){return materials.findById(id).orElseThrow(()->new ResourceNotFoundException("Material not found"));}
 public record ResourceFile(MaterialVersion version,byte[] bytes){}
}
